package com.aaliyun.leadnews.ai;import com.aaliyun.leadnews.ai.exception.AiExceptions;import com.aaliyun.leadnews.ai.support.AiCallExecutor;import org.junit.jupiter.api.Test;import java.time.Duration;import java.util.concurrent.*;import static org.assertj.core.api.Assertions.assertThatThrownBy;
class BulkheadTest {@Test void rejectsBeyondLimit()throws Exception{try(var x=new AiCallExecutor(TestFixtures.properties(Duration.ofSeconds(2),0,1))){var entered=new CountDownLatch(1);var release=new CountDownLatch(1);Thread t=Thread.ofVirtual().start(()->x.execute(()->{entered.countDown();try{release.await();}catch(InterruptedException ignored){}return null;}));entered.await();assertThatThrownBy(()->x.execute(()->null)).isInstanceOf(AiExceptions.CapacityExceeded.class);release.countDown();t.join();}}}
